@* Displays a single task card with move buttons *@

<div class="board-task-card">
    <h4>@Task.Title</h4>
    <p class="assignee">@Task.Assignee</p>
    <span class="priority-badge priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    <span class="due-date">@Task.DueDate.ToString("MMM dd")</span>

    <div class="card-actions">
        @if (CanMoveLeft)
        {
            <button class="btn-move" @onclick="MoveLeftClicked">Move Left</button>
        }
        @if (CanMoveRight)
        {
            <button class="btn-move" @onclick="MoveRightClicked">Move Right</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public TaskItem Task { get; set; } = default!;

    [Parameter]
    public bool CanMoveLeft { get; set; }

    [Parameter]
    public bool CanMoveRight { get; set; }

    [Parameter]
    public EventCallback OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback OnMoveRight { get; set; }

    private async Task MoveLeftClicked() => await OnMoveLeft.InvokeAsync();
    private async Task MoveRightClicked() => await OnMoveRight.InvokeAsync();
}

@* Inline form to add a new task within a column *@

<div class="board-add-task-form">
    <input type="text" placeholder="Title" @bind="title" />
    <input type="text" placeholder="Assignee" @bind="assignee" />
    <select @bind="priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" />

    <div class="form-actions">
        <button class="btn-save" @onclick="Save">Save</button>
        <button class="btn-cancel" @onclick="Cancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public EventCallback<NewTaskModel> OnSave { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnCancel { get; set; }

    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);

    private async Task Save()
    {
        if (string.IsNullOrWhiteSpace(title))
            return;

        await OnSave.InvokeAsync(new NewTaskModel(title, assignee, priority, dueDate));
    }

    private async Task Cancel() => await OnCancel.InvokeAsync();

    public record NewTaskModel(string Title, string Assignee, string Priority, DateTime DueDate);
}

@* A single Kanban column displaying tasks and an add-task form *@

<div class="board-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="task-count">@Tasks.Count</span>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <BoardTaskCard Task="task"
                           CanMoveLeft="CanMoveLeft"
                           CanMoveRight="CanMoveRight"
                           OnMoveLeft="() => MoveTask(task.Id, Direction.Left)"
                           OnMoveRight="() => MoveTask(task.Id, Direction.Right)" />
        }
    </div>

    @if (showForm)
    {
        <BoardAddTaskForm OnSave="HandleSave" OnCancel="HideForm" />
    }
    else
    {
        <button class="btn-add-task" @onclick="ShowForm">Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public string ColumnName { get; set; } = string.Empty;

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public bool CanMoveLeft { get; set; }

    [Parameter]
    public bool CanMoveRight { get; set; }

    [Parameter]
    public EventCallback<(int TaskId, Direction Direction)> OnMoveTask { get; set; }

    [Parameter]
    public EventCallback<BoardAddTaskForm.NewTaskModel> OnAddTask { get; set; }

    private bool showForm;

    private void ShowForm() => showForm = true;
    private void HideForm() => showForm = false;

    private async Task MoveTask(int taskId, Direction direction)
    {
        await OnMoveTask.InvokeAsync((taskId, direction));
    }

    private async Task HandleSave(BoardAddTaskForm.NewTaskModel model)
    {
        await OnAddTask.InvokeAsync(model);
        showForm = false;
    }

    public enum Direction { Left, Right }
}

@* Summary statistics bar for the Kanban board *@

<div class="board-stats-bar">
    <span class="stat">Total: <strong>@Total</strong></span>
    <span class="stat">To Do: <strong>@ToDo</strong></span>
    <span class="stat">In Progress: <strong>@InProgress</strong></span>
    <span class="stat">Done: <strong>@DoneCount</strong></span>
    <span class="stat stat-overdue">Overdue: <strong>@Overdue</strong></span>
</div>

@code {
    [Parameter] public int Total { get; set; }
    [Parameter] public int ToDo { get; set; }
    [Parameter] public int InProgress { get; set; }
    [Parameter] public int DoneCount { get; set; }
    [Parameter] public int Overdue { get; set; }
}

@* Search bar for filtering tasks by title *@

<div class="board-search-bar">
    <input type="text" placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="OnInput" />
</div>

@code {
    [Parameter]
    public string SearchText { get; set; } = string.Empty;

    [Parameter]
    public EventCallback<string> SearchTextChanged { get; set; }

    private async Task OnInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? string.Empty;
        await SearchTextChanged.InvokeAsync(value);
    }
}

@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Kanban Board</h1>

@if (loading)
{
    <p>Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error">@errorMessage</p>
}
else
{
    <BoardStatsBar Total="@allTasks.Count"
                   ToDo="@GetColumnTasks("To Do").Count"
                   InProgress="@GetColumnTasks("In Progress").Count"
                   DoneCount="@GetColumnTasks("Done").Count"
                   Overdue="@allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <BoardSearchBar SearchText="@searchText" SearchTextChanged="OnSearchChanged" />

    <div class="board-columns">
        <BoardColumn ColumnName="To Do"
                     Tasks="@GetFilteredColumnTasks("To Do")"
                     CanMoveLeft="false"
                     CanMoveRight="true"
                     OnMoveTask="args => HandleMoveTask(args.TaskId, args.Direction, \"To Do\")"
                     OnAddTask="model => HandleAddTask(model, \"To Do\")" />

        <BoardColumn ColumnName="In Progress"
                     Tasks="@GetFilteredColumnTasks("In Progress")"
                     CanMoveLeft="true"
                     CanMoveRight="true"
                     OnMoveTask="args => HandleMoveTask(args.TaskId, args.Direction, \"In Progress\")"
                     OnAddTask="model => HandleAddTask(model, \"In Progress\")" />

        <BoardColumn ColumnName="Done"
                     Tasks="@GetFilteredColumnTasks("Done")"
                     CanMoveLeft="true"
                     CanMoveRight="false"
                     OnMoveTask="args => HandleMoveTask(args.TaskId, args.Direction, \"Done\")"
                     OnAddTask="model => HandleAddTask(model, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool loading = true;
    private string? errorMessage;

    private static readonly string[] ColumnOrder = { "To Do", "In Progress", "Done" };

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status)
        => allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumnTasks(string status)
    {
        var tasks = GetColumnTasks(status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
        }
        return tasks;
    }

    private void OnSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task HandleMoveTask(int taskId, BoardColumn.Direction direction, string currentStatus)
    {
        var currentIndex = Array.IndexOf(ColumnOrder, currentStatus);
        var newIndex = direction == BoardColumn.Direction.Left ? currentIndex - 1 : currentIndex + 1;

        if (newIndex < 0 || newIndex >= ColumnOrder.Length)
            return;

        var newStatus = ColumnOrder[newIndex];

        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);

            var task = allTasks.First(t => t.Id == taskId);
            var index = allTasks.IndexOf(task);
            allTasks[index] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleAddTask(BoardAddTaskForm.NewTaskModel model, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
            // CreateTaskAsync returns a task with default status; ensure it's in the correct column
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

.board-columns {
    display: flex;
    gap: 1rem;
    margin-top: 1rem;
}

.error {
    color: red;
    font-weight: bold;
}

::deep .board-stats-bar {
    display: flex;
    gap: 1.5rem;
    padding: 0.75rem 1rem;
    background: #f0f0f0;
    border-radius: 6px;
    margin-bottom: 1rem;
}

::deep .stat-overdue strong {
    color: red;
}

::deep .board-search-bar {
    margin-bottom: 1rem;
}

::deep .board-search-bar input {
    width: 100%;
    padding: 0.5rem;
    font-size: 1rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

::deep .board-column {
    flex: 1;
    background: #f8f9fa;
    border-radius: 8px;
    padding: 1rem;
    min-width: 250px;
}

::deep .column-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

::deep .column-header h3 {
    margin: 0;
}

::deep .task-count {
    background: #6c757d;
    color: white;
    border-radius: 12px;
    padding: 0.1rem 0.6rem;
    font-size: 0.85rem;
}

::deep .board-task-card {
    background: white;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
    margin-bottom: 0.5rem;
}

::deep .board-task-card h4 {
    margin: 0 0 0.25rem;
    font-size: 0.95rem;
}

::deep .board-task-card .assignee {
    margin: 0 0 0.25rem;
    font-size: 0.85rem;
    color: #555;
}

::deep .priority-badge {
    display: inline-block;
    padding: 0.1rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: bold;
    color: white;
    margin-right: 0.5rem;
}

::deep .priority-high {
    background-color: red;
}

::deep .priority-medium {
    background-color: #f0ad4e;
}

::deep .priority-low {
    background-color: green;
}

::deep .due-date {
    font-size: 0.8rem;
    color: #666;
}

::deep .card-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

::deep .btn-move {
    font-size: 0.75rem;
    padding: 0.2rem 0.5rem;
    border: 1px solid #007bff;
    background: white;
    color: #007bff;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-move:hover {
    background: #007bff;
    color: white;
}

::deep .btn-add-task {
    width: 100%;
    padding: 0.5rem;
    margin-top: 0.5rem;
    border: 1px dashed #adb5bd;
    background: transparent;
    color: #6c757d;
    border-radius: 4px;
    cursor: pointer;
}

::deep .board-add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-top: 0.5rem;
    padding: 0.75rem;
    background: white;
    border: 1px solid #dee2e6;
    border-radius: 6px;
}

::deep .board-add-task-form input,
::deep .board-add-task-form select {
    padding: 0.4rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

::deep .form-actions {
    display: flex;
    gap: 0.5rem;
}

::deep .btn-save {
    background: #28a745;
    color: white;
    border: none;
    padding: 0.4rem 0.8rem;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-cancel {
    background: #dc3545;
    color: white;
    border: none;
    padding: 0.4rem 0.8rem;
    border-radius: 4px;
    cursor: pointer;
}

