@* A single Kanban column displaying tasks and an add-task form *@

<div class="board-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="task-count">@Tasks.Count</span>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <BoardTaskCard Task="task"
                           CanMoveLeft="CanMoveLeft"
                           CanMoveRight="CanMoveRight"
                           OnMoveLeft="() => MoveTask(task.Id, Direction.Left)"
                           OnMoveRight="() => MoveTask(task.Id, Direction.Right)" />
        }
    </div>

    @if (showForm)
    {
        <BoardAddTaskForm OnSave="HandleSave" OnCancel="HideForm" />
    }
    else
    {
        <button class="btn-add-task" @onclick="ShowForm">Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public string ColumnName { get; set; } = string.Empty;

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public bool CanMoveLeft { get; set; }

    [Parameter]
    public bool CanMoveRight { get; set; }

    [Parameter]
    public EventCallback<(int TaskId, Direction Direction)> OnMoveTask { get; set; }

    [Parameter]
    public EventCallback<BoardAddTaskForm.NewTaskModel> OnAddTask { get; set; }

    private bool showForm;

    private void ShowForm() => showForm = true;
    private void HideForm() => showForm = false;

    private async Task MoveTask(int taskId, Direction direction)
    {
        await OnMoveTask.InvokeAsync((taskId, direction));
    }

    private async Task HandleSave(BoardAddTaskForm.NewTaskModel model)
    {
        await OnAddTask.InvokeAsync(model);
        showForm = false;
    }

    public enum Direction { Left, Right }
}

