@* Summary statistics bar for the Kanban board *@

<div class="board-stats-bar">
    <span class="stat">Total: <strong>@Total</strong></span>
    <span class="stat">To Do: <strong>@ToDo</strong></span>
    <span class="stat">In Progress: <strong>@InProgress</strong></span>
    <span class="stat">Done: <strong>@DoneCount</strong></span>
    <span class="stat stat-overdue">Overdue: <strong>@Overdue</strong></span>
</div>

@code {
    [Parameter] public int Total { get; set; }
    [Parameter] public int ToDo { get; set; }
    [Parameter] public int InProgress { get; set; }
    [Parameter] public int DoneCount { get; set; }
    [Parameter] public int Overdue { get; set; }
}

@* Search bar for filtering tasks by title *@

<div class="board-search-bar">
    <input type="text" placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="OnInput" />
</div>

@code {
    [Parameter]
    public string SearchText { get; set; } = string.Empty;

    [Parameter]
    public EventCallback<string> SearchTextChanged { get; set; }

    private async Task OnInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? string.Empty;
        await SearchTextChanged.InvokeAsync(value);
    }
}

@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Kanban Board</h1>

@if (loading)
{
    <p>Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error">@errorMessage</p>
}
else
{
    <BoardStatsBar Total="@allTasks.Count"
                   ToDo="@GetColumnTasks("To Do").Count"
                   InProgress="@GetColumnTasks("In Progress").Count"
                   DoneCount="@GetColumnTasks("Done").Count"
                   Overdue="@allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <BoardSearchBar SearchText="@searchText" SearchTextChanged="OnSearchChanged" />

    <div class="board-columns">
        <BoardColumn ColumnName="To Do"
                     Tasks="@GetFilteredColumnTasks("To Do")"
                     CanMoveLeft="false"
                     CanMoveRight="true"
                     OnMoveTask="args => HandleMoveTask(args.TaskId, args.Direction, \"To Do\")"
                     OnAddTask="model => HandleAddTask(model, \"To Do\")" />

        <BoardColumn ColumnName="In Progress"
                     Tasks="@GetFilteredColumnTasks("In Progress")"
                     CanMoveLeft="true"
                     CanMoveRight="true"
                     OnMoveTask="args => HandleMoveTask(args.TaskId, args.Direction, \"In Progress\")"
                     OnAddTask="model => HandleAddTask(model, \"In Progress\")" />

        <BoardColumn ColumnName="Done"
                     Tasks="@GetFilteredColumnTasks("Done")"
                     CanMoveLeft="true"
                     CanMoveRight="false"
                     OnMoveTask="args => HandleMoveTask(args.TaskId, args.Direction, \"Done\")"
                     OnAddTask="model => HandleAddTask(model, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool loading = true;
    private string? errorMessage;

    private static readonly string[] ColumnOrder = { "To Do", "In Progress", "Done" };

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status)
        => allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumnTasks(string status)
    {
        var tasks = GetColumnTasks(status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
        }
        return tasks;
    }

    private void OnSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task HandleMoveTask(int taskId, BoardColumn.Direction direction, string currentStatus)
    {
        var currentIndex = Array.IndexOf(ColumnOrder, currentStatus);
        var newIndex = direction == BoardColumn.Direction.Left ? currentIndex - 1 : currentIndex + 1;

        if (newIndex < 0 || newIndex >= ColumnOrder.Length)
            return;

        var newStatus = ColumnOrder[newIndex];

        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);

            var task = allTasks.First(t => t.Id == taskId);
            var index = allTasks.IndexOf(task);
            allTasks[index] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleAddTask(BoardAddTaskForm.NewTaskModel model, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
            // CreateTaskAsync returns a task with default status; ensure it's in the correct column
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

