toolArgs.file_text:
.board-columns {
    display: flex;
    gap: 1rem;
    margin-top: 1rem;
}

.error {
    color: red;
    font-weight: bold;
}

::deep .board-stats-bar {
    display: flex;
    gap: 1.5rem;
    padding: 0.75rem 1rem;
    background: #f0f0f0;
    border-radius: 6px;
    margin-bottom: 1rem;
}

::deep .stat-overdue strong {
    color: red;
}

::deep .board-search-bar {
    margin-bottom: 1rem;
}

::deep .board-search-bar input {
    width: 100%;
    padding: 0.5rem;
    font-size: 1rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

::deep .board-column {
    flex: 1;
    background: #f8f9fa;
    border-radius: 8px;
    padding: 1rem;
    min-width: 250px;
}

::deep .column-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

::deep .column-header h3 {
    margin: 0;
}

::deep .task-count {
    background: #6c757d;
    color: white;
    border-radius: 12px;
    padding: 0.1rem 0.6rem;
    font-size: 0.85rem;
}

::deep .board-task-card {
    background: white;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
    margin-bottom: 0.5rem;
}

::deep .board-task-card h4 {
    margin: 0 0 0.25rem;
    font-size: 0.95rem;
}

::deep .board-task-card .assignee {
    margin: 0 0 0.25rem;
    font-size: 0.85rem;
    color: #555;
}

::deep .priority-badge {
    display: inline-block;
    padding: 0.1rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: bold;
    color: white;
    margin-right: 0.5rem;
}

::deep .priority-high {
    background-color: red;
}

::deep .priority-medium {
    background-color: #f0ad4e;
}

::deep .priority-low {
    background-color: green;
}

::deep .due-date {
    font-size: 0.8rem;
    color: #666;
}

::deep .card-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

::deep .btn-move {
    font-size: 0.75rem;
    padding: 0.2rem 0.5rem;
    border: 1px solid #007bff;
    background: white;
    color: #007bff;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-move:hover {
    background: #007bff;
    color: white;
}

::deep .btn-add-task {
    width: 100%;
    padding: 0.5rem;
    margin-top: 0.5rem;
    border: 1px dashed #adb5bd;
    background: transparent;
    color: #6c757d;
    border-radius: 4px;
    cursor: pointer;
}

::deep .board-add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
