toolResult.textResultForLlm:
1. @page "/board"
2. @rendermode InteractiveServer
3. @inject ITaskService TaskService
4. 
5. <PageTitle>Kanban Board</PageTitle>
6. 
7. <h1>Kanban Board</h1>
8. 
9. @if (loading)
10. {
11.     <p>Loading tasks...</p>
12. }
13. else if (errorMessage is not null)
14. {
15.     <p class="error">@errorMessage</p>
16. }
17. else
18. {
19.     <BoardStatsBar Total="@allTasks.Count"
20.                    ToDo="@(GetColumnTasks("To Do").Count)"
21.                    InProgress="@(GetColumnTasks("In Progress").Count)"
22.                    DoneCount="@(GetColumnTasks("Done").Count)"
23.                    Overdue="@(allTasks.Count(t => t.DueDate < DateTime.Today))" />
24. 
25.     <BoardSearchBar SearchText="@searchText" SearchTextChanged="OnSearchChanged" />
26. 
27.     <div class="board-columns">
28.         @foreach (var col in columns)
29.         {
30.             var colIndex = Array.IndexOf(ColumnOrder, col);
31.             <BoardColumn ColumnName="@col"
32.                          Tasks="@GetFilteredColumnTasks(col)"
33.                          CanMoveLeft="@(colIndex > 0)"
34.                          CanMoveRight="@(colIndex < ColumnOrder.Length - 1)"
35.                          OnMoveTask="@(args => HandleMoveTask(args.TaskId, args.Direction, col))"
36.                          OnAddTask="@(model => HandleAddTask(model, col))" />
37.         }
38.     </div>
39. }
40. 
41. @code {
42.     private List<TaskItem> allTasks = new();
43.     private string searchText = string.Empty;
44.     private bool loading = true;
45.     private string? errorMessage;
46. 
47.     private static readonly string[] ColumnOrder = { "To Do", "In Progress", "Done" };
48.     private string[] columns = ColumnOrder;
49. 
50.     protected override async Task OnInitializedAsync()
51.     {
52.         try
53.         {
54.             allTasks = await TaskService.GetAllTasksAsync();
55.         }
56.         catch (Exception ex)
57.         {
58.             errorMessage = $"Failed to load tasks: {ex.Message}";
59.         }
60.         finally
61.         {
62.             loading = false;
63.         }
64.     }
65. 
66.     private List<TaskItem> GetColumnTasks(string status)
67.         => allTasks.Where(t => t.Status == status).ToList();
68. 
69.     private List<TaskItem> GetFilteredColumnTasks(string status)
70.     {
71.         var tasks = GetColumnTasks(status);
72.         if (!string.IsNullOrWhiteSpace(searchText))
73.         {
74.             tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
75.         }
76.         return tasks;
77.     }
78. 
79.     private void OnSearchChanged(string value)
80.     {
81.         searchText = value;
82.     }
83. 
84.     private async Task HandleMoveTask(int taskId, BoardColumn.Direction direction, string currentStatus)
85.     {
86.         var currentIndex = Array.IndexOf(ColumnOrder, currentStatus);
87.         var newIndex = direction == BoardColumn.Direction.Left ? currentIndex - 1 : currentIndex + 1;
88. 
89.         if (newIndex < 0 || newIndex >= ColumnOrder.Length)
90.             return;
91. 
92.         var newStatus = ColumnOrder[newIndex];
93. 
94.         try
95.         {
96.             await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
97. 
98.             var task = allTasks.First(t => t.Id == taskId);
99.             var index = allTasks.IndexOf(task);
100.             allTasks[index] = task with { Status = newStatus };
101.         }
102.         catch (Exception ex)
103.         {
104.             errorMessage = $"Failed to move task: {ex.Message}";
105.         }
106.     }
107. 
108.     private async Task HandleAddTask(BoardAddTaskForm.NewTaskModel model, string status)
109.     {
110.         try
111.         {
112.             var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
113.             // CreateTaskAsync returns a task with default status; ensure it's in the correct column
114.             allTasks.Add(newTask with { Status = status });
115.         }
116.         catch (Exception ex)
117.         {
118.             errorMessage = $"Failed to create task: {ex.Message}";
119.         }
120.     }
121. }
122.

